import React from 'react';
import { Navigate } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';

const ProtectedRoute = ({ children, requiredUserType, requiresApproval = true }) => {
  const { user, profile, loading, error } = useAuth();

  console.log('ProtectedRoute - user:', user?.id, 'profile:', profile, 'loading:', loading, 'error:', error);

  if (loading) {
    return (
      <div className="loading-screen">
        <div className="logo-icon">3D</div>
        <p>Loading...</p>
      </div>
    );
  }

  // If there's an error or profile is missing, redirect to login
  if (!user) {
    console.log('No user found, redirecting to login');
    return <Navigate to="/login" replace />;
  }

  if (!profile) {
    console.log('No profile found for user, redirecting to login');
    return <Navigate to="/login" replace />;
  }

  // Check if profile is incomplete (missing user_type)
  if (!profile.user_type) {
    console.warn('ProtectedRoute: Profile missing user_type:', profile);
    // TODO: Redirect to profile setup page instead of login
    // For now, allow access but log warning
  }

  // Check if user type matches required type
  if (requiredUserType && profile.user_type !== requiredUserType) {
    return <Navigate to="/dashboard" replace />;
  }

  // For artist-specific routes, check approval status
  // Allow pending artists to access profile and portfolio pages (requiresApproval = false)
  if (requiresApproval &&
      profile.user_type === 'artista' &&
      requiredUserType === 'artista' &&
      profile.approval_status !== 'approved') {

    console.log('ProtectedRoute: Artist not approved, redirecting to dashboard');
    return <Navigate to="/dashboard" replace />;
  }

  return children;
};

export default ProtectedRoute;
